import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.BWuWLRhz.js";const o="/architecture.svg",g=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"dev-guide/architecture.md","filePath":"dev-guide/architecture.md","lastUpdated":1783761619000}'),s={name:"dev-guide/architecture.md"};function n(c,e,d,l,h,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p><img src="'+o+'" alt="SwiftList architecture"></p><h2 id="process-split" tabindex="-1">Process split <a class="header-anchor" href="#process-split" aria-label="Permalink to &quot;Process split&quot;">​</a></h2><p>SwiftList runs as three separate processes, deliberately isolated by privilege level and lifetime:</p><ul><li><strong><code>SwiftList.Service</code></strong> — a Windows service running as <code>LocalSystem</code>. It owns all file indexing: reading the NTFS USN Journal and MFT for local drives, scanning and caching network shares, and answering search queries over a named pipe. Running this at SYSTEM level means it can read the raw volume metadata every user account is allowed to see, without granting the interactive App process elevated privileges it doesn&#39;t need.</li><li><strong><code>SwiftList.App</code></strong> — the per-user, session-level WPF application: the search windows, the Settings window, hotkey handling, and the Actions/QuickLook UI. It talks to the Service over a named pipe (<code>SearchService</code>/<code>UsnServicePipeServer</code> in <code>Core.Services</code>) and never touches the disk index directly.</li><li><strong><code>SwiftList.Service --hook</code></strong> — a small separate process hosting the low-level global keyboard hook, so a hook crash or a misbehaving foreground app can&#39;t take the main App process down with it.</li></ul><h2 id="shared-core" tabindex="-1">Shared Core <a class="header-anchor" href="#shared-core" aria-label="Permalink to &quot;Shared Core&quot;">​</a></h2><p><code>Core</code> is a class library referenced by both the Service and the App. It holds:</p><ul><li>The search engine (<code>Core/SearchIndex/Fzf/*</code>) — a fuzzy-matching implementation modeled on the <code>fzf</code> command-line tool&#39;s algorithm, plus a query parser (<code>SearchQueryParser</code>) for drive-letter targeting and path-mode search.</li><li>The runtime index (<code>Core/IndexV2/*</code>) — a memory-mapped, columnar snapshot format built from USN/MFT reads, with an in-memory delta overlay for changes since the last snapshot.</li><li>IPC contracts (<code>SearchRequestMessage</code>, <code>SearchResponseBinarySerializer</code>, ...) shared verbatim by both processes, so the App and Service always agree on the wire format.</li><li><code>Logger</code> — writes to per-process log files (<code>service.log</code>, <code>app.log</code>, <code>hook.log</code>), all readable (but not all writable) from the App&#39;s Settings → Service Status log viewer.</li></ul><h2 id="where-plugins-fit" tabindex="-1">Where plugins fit <a class="header-anchor" href="#where-plugins-fit" aria-label="Permalink to &quot;Where plugins fit&quot;">​</a></h2><p>Plugins are <code>.dll</code> assemblies referencing <code>PluginSdk</code> and are loaded by the App process (see <a href="./getting-started.html">Getting Started</a> and <a href="./packaging.html">Packaging &amp; Deployment</a>). Two plugins ship with SwiftList itself as first-class examples — <code>SwiftList.Plugins.CoreExtensions</code> (built-in file actions and the shell context-menu integration) and <code>SwiftList.Plugins.PinyinAlias</code> (pinyin aliasing for Chinese filenames) — see <a href="./examples.html">Example Plugins</a> for a walkthrough of both.</p><p>Plugins never talk to the Service directly; they interact with the App through the interfaces documented in the Plugin SDK Reference, and with the disk index (when they need custom indexed directories) through <code>DirectoryIndexerService</code>, which proxies to the Service on their behalf.</p>',11)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
